#!/usr/bin/env python3
"""Sync only Entire checkpoint refs; Brain syncing is disabled."""
import argparse, concurrent.futures, json, os, subprocess
from entire_cloud_policy import private_repo_allowed
from pathlib import Path
ROOT = Path(__file__).resolve().parent

def run(args, repo, timeout=180):
    env = dict(os.environ, ENTIRE_CLOUD_FORWARDING='1', GIT_TERMINAL_PROMPT='0')
    try:
        p = subprocess.run(args, cwd=repo, env=env, capture_output=True, text=True, timeout=timeout)
        return {'code':p.returncode, 'output':p.stdout+p.stderr}
    except subprocess.TimeoutExpired:
        return {'code':124,'output':'Timed out; retry from your logged-in terminal.'}

def sync(repo):
    result={'repo':repo.name,'path':str(repo)}
    allowed,reason=private_repo_allowed(repo)
    if not allowed:
        result['skipped']=reason;return result
    remote=run(['git','remote','get-url','entire'],repo)
    if remote['code']:
        result['skipped']='No Entire remote';return result
    refs=run(['git','for-each-ref','--format=%(refname)','refs/entire/checkpoints/'],repo)
    if refs['code']:
        result['checkpoints']=refs
    elif refs['output'].strip():
        result['checkpoints']=run(['git','push','entire','refs/entire/checkpoints/*:refs/entire/checkpoints/*'],repo)
        if result['checkpoints']['code']==0:
            local=run(['git','for-each-ref','--format=%(objectname) %(refname)','refs/entire/checkpoints/'],repo)
            remote_refs=run(['git','ls-remote','entire','refs/entire/checkpoints/*'],repo)
            def mapping(text):
                return {line.split()[1]:line.split()[0] for line in text.splitlines() if len(line.split())==2}
            left=mapping(local['output']);right=mapping(remote_refs['output']) if remote_refs['code']==0 else {}
            result['checkpoint_refs_verified']=sum(right.get(k)==v for k,v in left.items())
            result['checkpoint_refs_local']=len(left)
            result['verification_ok']=remote_refs['code']==0 and all(right.get(k)==v for k,v in left.items())
    else:result['checkpoints']={'code':0,'output':'No existing checkpoint refs to upload.'}
    result['memories']={'code':0,'output':'Brain cloud syncing disabled by user.'}
    return result

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--repo');args=parser.parse_args()
    paths=[Path(args.repo).resolve()] if args.repo else sorted(p for p in ROOT.iterdir() if p.is_dir() and (p/'.git').exists())
    rows=[]
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
        for future in concurrent.futures.as_completed(pool.submit(sync,p) for p in paths):
            r=future.result();rows.append(r)
            failed=any(r.get(k,{}).get('code',0)!=0 for k in ['checkpoints','memories']) or r.get('verification_ok') is False
            print(r['repo']+': '+('SKIPPED' if 'skipped' in r else 'NEEDS ATTENTION' if failed else 'SYNCED'),flush=True)
            if args.repo:
                for k in ['checkpoints','memories']:
                    if r.get(k,{}).get('code',0): print(r[k]['output'],flush=True)
            else:(ROOT/'entire-cloud-sync-results.json').write_text(json.dumps(rows,indent=2)+'\n')

    failures=sum(any(r.get(k,{}).get('code',0)!=0 for k in ['checkpoints','memories']) or r.get('verification_ok') is False for r in rows)
    skipped=sum('skipped' in r for r in rows)
    print(f"Finished: {len(rows)-failures-skipped} synced, {failures} need attention, {skipped} unavailable.",flush=True)
    raise SystemExit(1 if failures or skipped else 0)

